#[test]
fn test_serialize_empty_table() -> LuaResult<()> {
    let lua = Lua::new();

    let table = Value::Table(lua.create_table()?);
    let json = serde_json::to_string(&table.to_serializable()).unwrap();
    assert_eq!(json, "{}");

