            methods.add_method("method", |lua, this, ()| {
                let ud = lua.globals().get::<AnyUserData>("ud")?;
                assert_eq!(ud.call_method::<String>("method2", ())?, "method2");
                Ok(this.0.clone())
            });

            methods.add_method("method2", |_, _, ()| Ok("method2"));
        }
